18	function readError(name, reason) {
19	  return new CliError(`Error: ${name}: ${reason}`, 1);
20	}
21	
22	function isDirectory(path) {
23	  try {
24	    return fs.statSync(path).isDirectory();
25	  } catch {
26	    return false;
27	  }
28	}
