30	// Reads at most MAX_BYTES + 1 bytes from a file, so oversized inputs stop early.
31	function readFile(path) {
32	  let fd;
33	  try {
34	    fd = fs.openSync(path, 'r');
35	  } catch (err) {
36	    if (err.code === 'ENOENT' || err.code === 'ENOTDIR') throw readError(path, 'no such file');
37	    if (err.code === 'EISDIR' || isDirectory(path)) throw readError(path, 'is a directory');
38	    throw readError(path, 'cannot read');
39	  }
40	  try {
41	    if (fs.fstatSync(fd).isDirectory()) throw readError(path, 'is a directory');
42	    const buf = Buffer.alloc(MAX_BYTES + 1);
43	    let total = 0;
44	    while (total < buf.length) {
45	      const n = fs.readSync(fd, buf, total, buf.length - total, null);
46	      if (n === 0) break;
47	      total += n;
48	    }
49	    if (total > MAX_BYTES) throw readError(path, 'too large');
50	    return buf.subarray(0, total);
51	  } catch (err) {
52	    if (err instanceof CliError) throw err;
53	    throw readError(path, err.code === 'EISDIR' ? 'is a directory' : 'cannot read');
54	  } finally {
