81	  while (stack.length > 0) {
82	    const [v, depth] = stack.pop();
83	    if (v === null || typeof v !== 'object') continue;
84	    if (depth + 1 > MAX_DEPTH) return true;
85	    for (const child of Object.values(v)) stack.push([child, depth + 1]);
