100	  try {
101	    value = JSON.parse(text);
102	  } catch {
103	    throw new CliError(`Error: ${name}: invalid JSON`, 3);
104	  }
105	  if (tooDeep(value)) throw new CliError(`Error: ${name}: too deep`, 3);
106	  return value;
107	}
