109	async function main(args) {
110	  if (args.length < 1 || args.length > 2) throw new CliError(USAGE, 2);
111	  const [patchArg, docArg = STDIN] = args;
112	  if (patchArg === STDIN && docArg === STDIN) throw new CliError(USAGE, 2);
113	  const patch = await load(patchArg);
114	  const doc = await load(docArg);
115	  let result;
116	  try {
117	    result = applyPatch(doc, patch);
118	  } catch (err) {
119	    if (err instanceof PatchError) throw new CliError(`Error: ${err.message}`, 4);
120	    throw err;
121	  }
